// Worldgen: the height range a jigsaw piece must stand in, a gravity processor's offset, the Pokemon Centers a village
// draws, and the generated files for the feature-placed structures, the structure odds and the galarica ages (the
// checks on generated files pass once port.py has run)
import { cpSync, existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { check } from "../harness.mjs";

const pack = join(dirname(fileURLToPath(import.meta.url)), "../../../development_behavior_packs/cobblemon");
const json = (path) => (existsSync(join(pack, path)) ? JSON.parse(readFileSync(join(pack, path), "utf-8")) : undefined);
// worldgen.js imports @minecraft/server, so like main.js it is loaded from a copy in a folder marked as ES modules
const copy = mkdtempSync(join(tmpdir(), "cobblemon-worldgen-"));
writeFileSync(join(copy, "package.json"), JSON.stringify({ type: "module" }));
for (const file of ["worldgen.js", "jigsaw.js"]) if (existsSync(join(pack, "scripts", file))) cpSync(join(pack, "scripts", file), join(copy, file));
const { heightRangeOk, groundOffset, pokecenterRolls, SEA_LEVEL } = await import(pathToFileURL(join(copy, "worldgen.js")).href);

// StructureMixin: a piece's bottom (its box's y0 plus one, Java's start being on the heightmap) within sea level + [min,
// max], or the start is discarded
const piece = { hr: [2, 250] };
check("a piece on a top block one over sea level stands (its bottom two over)", heightRangeOk(piece, { y0: SEA_LEVEL + 1 }));
check("a piece on the sea's surface is refused", !heightRangeOk(piece, { y0: SEA_LEVEL - 1 }) && !heightRangeOk(piece, { y0: SEA_LEVEL }));
check("a piece 250 over sea level is refused", !heightRangeOk(piece, { y0: SEA_LEVEL + 250 }));
check("a piece with no height range stands anywhere", heightRangeOk({}, { y0: 10 }) && heightRangeOk(undefined, { y0: 10 }));

// the pool entry's third field: terrain matching is a gravity processor at -1, a rigid piece's own offset otherwise
check("terrain matching drops a piece to the top block", groundOffset(1) === -1);
check("a sandpit clearing sinks six", groundOffset(-6) === -6);
check("a rigid piece reads as -1 if ever asked", groundOffset(0) === -1 && groundOffset(undefined) === -1);

// CobblemonStructures.pokecenterWeight: 35 against the houses pool, one roll per other house, at most four more
check("a village of one house draws no second center", pokecenterRolls("plains", 1, () => 0) === 0);
check("every roll won gives at most four more", pokecenterRolls("plains", 12, () => 0) === 4);
check("every roll lost gives none", pokecenterRolls("desert", 12, () => 1) === 0);
check("a roll just under 35 in 123 wins in plains", pokecenterRolls("plains", 2, () => 35 / 123 - 0.001) === 1 && pokecenterRolls("plains", 2, () => 35 / 123 + 0.001) === 0);

// generated by port.py (tools/port_worldgen.py): pass after the port runs
const hoard = json("feature_rules/habitats_treasure_hoard_rule.json")?.["minecraft:feature_rules"];
check("the Treasure Hoard rule rolls one chunk in 80 at y -58..-25 underground", hoard?.distribution?.scatter_chance?.denominator === 80
    && JSON.stringify(hoard?.distribution?.y?.extent) === "[-58,-25]" && hoard?.conditions?.placement_pass === "underground_pass", JSON.stringify(hoard?.distribution));
check("the Treasure Hoard snaps to the floor, sinks and picks a template", json("features/habitats_treasure_hoard.json")?.["minecraft:snap_to_surface_feature"]?.feature_to_snap === "cobblemon:habitats_treasure_hoard_sink"
    && json("features/habitats_treasure_hoard_pick.json")?.["minecraft:weighted_random_feature"]?.features?.length === 8);
check("the Deep Crypt rule rolls one chunk in 3 in the deep dark with both templates", json("feature_rules/ruins_deep_crypt_rule.json")?.["minecraft:feature_rules"]?.distribution?.scatter_chance?.denominator === 3
    && json("features/ruins_deep_crypt_pick.json")?.["minecraft:weighted_random_feature"]?.features?.length === 2);
check("the Abandoned Fortress sits in the lava sea at y 31", json("feature_rules/habitats_abandoned_fortress_rule.json")?.["minecraft:feature_rules"]?.distribution?.y === 31);
check("the crumbling arch's template is converted", existsSync(join(pack, "structures/cobblemon/ruins_crumbling_arch.mcstructure")));
const tower = json("feature_rules/ruins_deserted_tower_ruins_rule.json")?.["minecraft:feature_rules"]?.distribution?.scatter_chance?.denominator;
check("a desert ruin shares its cell with the desert ruins only (about one in 5400)", tower !== undefined && tower < 7000, String(tower));
check("galarica bushes come at four ages 8:3:3:2", JSON.stringify(json("features/galarica_bush_wild.json")?.["minecraft:weighted_random_feature"]?.features?.map((f) => f[1])) === "[8,3,3,2]");
check("revival herbs search each column's cave floors", json("features/revival_herb_column.json")?.["minecraft:search_feature"]?.places_feature === "cobblemon:revival_herb_wild");
let jigsaw;
try { jigsaw = await import(pathToFileURL(join(copy, "jigsaw.js")).href); } catch (e) { }
check("a bug mound piece carries its height range over sea level", JSON.stringify(jigsaw?.JIGSAW_PIECES?.habitats_bug_mound1?.hr) === "[2,250]", JSON.stringify(jigsaw?.JIGSAW_PIECES?.habitats_bug_mound1));
check("a sandpit clearing piece carries its gravity offset", (jigsaw?.JIGSAW_POOLS?.["cobblemon:habitats/sandpit_clearing"]?.e ?? []).some((e) => e[2] < 0), JSON.stringify(jigsaw?.JIGSAW_POOLS?.["cobblemon:habitats/sandpit_clearing"]?.e?.slice(0, 2)));
